import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.BkO3HzvX.js";const k=JSON.parse('{"title":"Installation and platforms","description":"","frontmatter":{},"headers":[],"relativePath":"guides/installation-platforms.md","filePath":"guides/installation-platforms.md"}'),n={name:"guides/installation-platforms.md"};function p(l,a,o,h,d,r){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="installation-and-platforms" tabindex="-1">Installation and platforms <a class="header-anchor" href="#installation-and-platforms" aria-label="Permalink to &quot;Installation and platforms&quot;">​</a></h1><p>Neony renders Python-built DOM trees inside a native WebView. Installing the Python package is necessary but not always sufficient: the WebView and some optional desktop integrations are supplied by the operating system.</p><h2 id="python-environments" tabindex="-1">Python environments <a class="header-anchor" href="#python-environments" aria-label="Permalink to &quot;Python environments&quot;">​</a></h2><p>For an application installed from the package index:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> neony</span></span></code></pre></div><p>For a checkout of this repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>The repository&#39;s recommended commands use <code>uv run</code>, for example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gallery</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check_all.py</span></span></code></pre></div><p><code>package.json</code> is only for the JavaScript runtime tests. A clean checkout has no tracked <code>node_modules/</code>; <code>scripts/check_all.py</code> runs <code>npm ci</code> automatically when the directory is absent.</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><p>The project develops and verifies primarily on Linux Wayland. The native WebView binding links against the <strong>WebKitGTK 4.1</strong> API (GTK 3, libsoup 3), so every distribution needs the package that provides <code>libwebkit2gtk-4.1.so.0</code>. Package names differ across distributions; the commands below cover the common ones.</p><h3 id="development-dependencies" tabindex="-1">Development dependencies <a class="header-anchor" href="#development-dependencies" aria-label="Permalink to &quot;Development dependencies&quot;">​</a></h3><p>Debian and Ubuntu:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libwebkit2gtk-4.1-dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libgtk-3-dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libxdo-dev</span></span></code></pre></div><p>Fedora:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dnf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webkit2gtk4.1-devel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gtk3-devel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libxdo-devel</span></span></code></pre></div><p>Arch Linux:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --needed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webkit2gtk-4.1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gtk3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xdotool</span></span></code></pre></div><p>openSUSE:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zypper</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libwebkit2gtk-4_1-0-devel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gtk3-devel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libxdo-devel</span></span></code></pre></div><blockquote><p>Each <code>-dev</code>/<code>-devel</code>/plain package above pulls in the matching WebKitGTK 4.1 runtime, GTK 3, and libsoup 3 automatically through the dependency graph.</p></blockquote><h3 id="runtime-dependencies-for-a-packaged-application" tabindex="-1">Runtime dependencies for a packaged application <a class="header-anchor" href="#runtime-dependencies-for-a-packaged-application" aria-label="Permalink to &quot;Runtime dependencies for a packaged application&quot;">​</a></h3><p>A packaged application needs the matching WebKitGTK <strong>runtime</strong> rather than the compiler headers alone. Install only the runtime package on the target machine:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Debian/Ubuntu : sudo apt-get install libwebkit2gtk-4.1-0</span></span>
<span class="line"><span>Fedora        : sudo dnf install webkit2gtk4.1</span></span>
<span class="line"><span>Arch Linux    : sudo pacman -S webkit2gtk-4.1</span></span>
<span class="line"><span>openSUSE      : sudo zypper install libwebkit2gtk-4_1-0</span></span></code></pre></div><blockquote><p>Note for Arch users: the upstream packaging workflow previously documented <code>webkit2gtk-6.0</code>, but that provides the GTK 4 / newer API and is <strong>not</strong> the one this framework links. The framework targets the WebKitGTK 4.1 API, so install <code>webkit2gtk-4.1</code>.</p></blockquote><h3 id="optional-system-tray-dependency" tabindex="-1">Optional system tray dependency <a class="header-anchor" href="#optional-system-tray-dependency" aria-label="Permalink to &quot;Optional system tray dependency&quot;">​</a></h3><p>The native tray integration dynamically loads this library at runtime, so it is optional rather than a hard link:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Debian/Ubuntu : libayatana-appindicator3-1  (+ libayatana-appindicator3-dev for building)</span></span>
<span class="line"><span>Fedora        : libayatana-appindicator-gtk3</span></span>
<span class="line"><span>Arch Linux    : libayatana-appindicator</span></span>
<span class="line"><span>openSUSE      : libayatana-appindicator3-1</span></span></code></pre></div><p>If it is unavailable, the windowed application still runs; tray creation is logged and skipped by the application layer.</p><h3 id="wayland-x11-and-ci" tabindex="-1">Wayland, X11, and CI <a class="header-anchor" href="#wayland-x11-and-ci" aria-label="Permalink to &quot;Wayland, X11, and CI&quot;">​</a></h3><p>Wayland is the primary Linux desktop verification target. The Linux blur path uses the compositor&#39;s background-effect protocol where supported; positioning is also subject to Wayland restrictions.</p><p>X11 is not a complete support target at this stage. CI uses <code>xvfb-run</code> for headless startup smoke tests, which proves that demos reach the event loop but does not prove every X11 desktop behavior or rendering result.</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>Windows uses the operating system&#39;s WebView2 runtime. Install or enable the WebView2 runtime before running an application. Native window materials such as Acrylic and Mica depend on the platform and window configuration.</p><p>The project has Windows packaging support in the Nuitka workflow, but individual features should still be verified on the target Windows version before shipping.</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>macOS uses WKWebView supplied by the system. File dialogs use <code>osascript</code> and transparent windows can request a native blur effect. WKWebView does not expose all filesystem metadata in a web drop event, so applications that depend on file paths should use the Neony native drop channel and test on the target OS.</p><p>The macOS runtime and HiDPI/mixed-DPI behavior are not fully covered by the repository&#39;s Linux CI; treat those as platform-specific verification work.</p><h2 id="native-file-dialogs" tabindex="-1">Native file dialogs <a class="header-anchor" href="#native-file-dialogs" aria-label="Permalink to &quot;Native file dialogs&quot;">​</a></h2><p>The public async methods are:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.open_file()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">paths </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.open_files()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">destination </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.save_file(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">default_name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;output.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">folder </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.select_folder()</span></span></code></pre></div><p>The worker selects the platform implementation:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Linux   → zenity when available, otherwise tkinter</span></span>
<span class="line"><span>macOS   → osascript</span></span>
<span class="line"><span>Windows → PowerShell</span></span>
<span class="line"><span>Other   → tkinter fallback</span></span></code></pre></div><p>The call runs in an executor thread, so the application&#39;s asyncio loop can keep serving other work while the picker is open. A cancelled single-selection call returns <code>None</code>; a cancelled multi-selection call returns <code>[]</code>. File filters are passed as <code>(label, pattern)</code> pairs, for example:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">filetypes </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PNG images&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;All files&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]</span></span></code></pre></div><p>If a platform command or fallback cannot open, the public API normalizes the usual failure/cancel result to the same empty shape. Test picker behavior on the platform where the application will ship.</p><h2 id="common-symptoms" tabindex="-1">Common symptoms <a class="header-anchor" href="#common-symptoms" aria-label="Permalink to &quot;Common symptoms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>First checks</th></tr></thead><tbody><tr><td>WebView fails to start on Linux</td><td>Confirm the WebKitGTK runtime and GTK libraries are installed; check the process stderr.</td></tr><tr><td>Tray icon is missing</td><td>Install <code>libayatana-appindicator</code>; tray creation is optional and may be skipped.</td></tr><tr><td>File picker does not appear</td><td>Check <code>zenity</code>/<code>osascript</code>/PowerShell or tkinter, plus the display/session environment.</td></tr><tr><td>A demo exits immediately in CI</td><td>Run it under <code>xvfb-run</code>; use <code>tests/smoke_demos.py</code> rather than opening a real desktop window in a static check.</td></tr><tr><td>A transparent window has no blur</td><td>Check compositor/platform support; blur failure is non-fatal and leaves the window usable.</td></tr></tbody></table><p>For a first working application, return to <a href="/neony/getting-started.html">Getting started</a>. For exact configuration fields, see the <a href="/neony/api/">API reference</a>.</p>`,50)])])}const g=s(n,[["render",p]]);export{k as __pageData,g as default};
